import json

def transform_simple(grid):
    """Keep only the 2-rectangle, remove all 1s"""
    result = [row[:] for row in grid]

    # Find 2 cells (rectangle)
    rect_cells = set((r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == 2)

    # Set all non-2 cells to 0
    for r in range(len(result)):
        for c in range(len(result[0])):
            if (r, c) not in rect_cells:
                result[r][c] = 0

    return result

output = transform_simple(grid)

print("Simple version (only 2s remain):")
for row in output[:10]:
    print(' '.join(map(str, row)))

